params.css:
#sheet > *{width:auto;max-width:none;margin-right:0;}
#sheet .inner > *{width:auto;max-width:none;margin-right:0;}
#sheet main > *{width:auto;max-width:none;margin-right:0;}
#sheet .frame > *{width:auto;max-width:none;margin-right:0;}
#sheet .card > *{width:auto;max-width:none;margin-right:0;}
#sheet > *:nth-child(odd){background:#f0f3f6;margin-left:0;margin-right:14%;}
#sheet .inner > *:nth-child(odd){background:#f0f3f6;margin-left:0;margin-right:14%;}
#sheet main > *:nth-child(odd){background:#f0f3f6;margin-left:0;margin-right:14%;}
#sheet .frame > *:nth-child(odd){background:#f0f3f6;margin-left:0;margin-right:14%;}
#sheet .card > *:nth-child(odd){background:#f0f3f6;margin-left:0;margin-right:14%;}
#sheet > *:nth-child(even){background:#fff;margin-left:14%;margin-right:0;}
#sheet .inner > *:nth-child(even){background:#fff;margin-left:14%;margin-right:0;}
#sheet main > *:nth-child(even){background:#fff;margin-left:14%;margin-right:0;}
#sheet .frame > *:nth-child(even){background:#fff;margin-left:14%;margin-right:0;}
#sheet .card > *:nth-child(even){background:#fff;margin-left:14%;margin-right:0;}
#sheet > *:first-child:not(.frame):not(.card):not(.inner){background:#1f2a36;color:#f3f6f9;margin-left:0;margin-right:0;}
#sheet .inner > *:first-child:not(.frame):not(.card):not(.inner){background:#1f2a36;color:#f3f6f9;margin-left:0;margin-right:0;}
#sheet main > *:first-child:not(.frame):not(.card):not(.inner){background:#1f2a36;color:#f3f6f9;margin-left:0;margin-right:0;}
#sheet .frame > *:first-child:not(.frame):not(.card):not(.inner){background:#1f2a36;color:#f3f6f9;margin-left:0;margin-right:0;}
#sheet .card > *:first-child:not(.frame):not(.card):not(.inner){background:#1f2a36;color:#f3f6f9;margin-left:0;margin-right:0;}
#sheet > *:first-child:not(.frame):not(.card):not(.inner) *{color:#f3f6f9;}
#sheet .inner > *:first-child:not(.frame):not(.card):not(.inner) *{color:#f3f6f9;}
#sheet main > *:first-child:not(.frame):not(.card):not(.inner) *{color:#f3f6f9;}
#sheet .frame > *:first-child:not(.frame):not(.card):not(.inner) *{color:#f3f6f9;}
#sheet .card > *:first-child:not(.frame):not(.card):not(.inner) *{color:#f3f6f9;}
#sheet .frame, #sheet .inner{border:0;}
#sheet .inner .frame, #sheet .inner{border:0;}
#sheet main .frame, #sheet .inner{border:0;}
#sheet .frame .frame, #sheet .inner{border:0;}
#sheet .card .frame, #sheet .inner{border:0;}
#sheet table.items td{border-color:#c8d1d9;}
#sheet .inner table.items td{border-color:#c8d1d9;}
#sheet main table.items td{border-color:#c8d1d9;}
#sheet .frame table.items td{border-color:#c8d1d9;}
#sheet .card table.items td{border-color:#c8d1d9;}
#sheet table.items th{border-color:#c8d1d9;}
#sheet .inner table.items th{border-color:#c8d1d9;}
#sheet main table.items th{border-color:#c8d1d9;}
#sheet .frame table.items th{border-color:#c8d1d9;}
#sheet .card table.items th{border-color:#c8d1d9;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet table.items{table-layout:fixed;}
#sheet .inner table.items{table-layout:fixed;}
#sheet main table.items{table-layout:fixed;}
#sheet .frame table.items{table-layout:fixed;}
#sheet .card table.items{table-layout:fixed;}
#sheet table.items th{overflow-wrap:anywhere;}
#sheet .inner table.items th{overflow-wrap:anywhere;}
#sheet main table.items th{overflow-wrap:anywhere;}
#sheet .frame table.items th{overflow-wrap:anywhere;}
#sheet .card table.items th{overflow-wrap:anywhere;}
#sheet table.items td{overflow-wrap:anywhere;}
#sheet .inner table.items td{overflow-wrap:anywhere;}
#sheet main table.items td{overflow-wrap:anywhere;}
#sheet .frame table.items td{overflow-wrap:anywhere;}
#sheet .card table.items td{overflow-wrap:anywhere;}
#sheet > .frame,#sheet .frame > .frame,#sheet > .card,#sheet .frame > .card,#sheet > .inner,#sheet .frame > .inner{margin-left:0;margin-right:0;background:transparent;color:inherit;}
